most_repeated_storage_engine_query.text:
SET DC_KIND="DENSE";
SELECT
[Department  current structure  (34)].[Department Number (322)] AS [Department  current structure  (34)$Department Number (322)],
SUM([Allocation Bridge  derived  (130)].[Allocated Amount  stored  (624)]) AS [$Measure0], COUNT()
FROM [Allocation Bridge  derived  (130)]
	LEFT OUTER JOIN [Department  current structure  (34)] ON [Allocation Bridge  derived  (130)].[Department Key (622)]=[Department  current structure  (34)].[Department Key (320)];

